/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAs = require( './as/get.js' );
var setAs = require( './as/set.js' );

var getCross = require( './cross/get.js' );
var setCross = require( './cross/set.js' );

var getFields = require( './fields/get.js' );
var setFields = require( './fields/set.js' );

var getOps = require( './ops/get.js' );
var setOps = require( './ops/set.js' );

var getProperties = require( './properties/get.js' );


// VARIABLES //

var debug = logger( 'vega:aggregate-transform:main' );


// MAIN //

/**
* Aggregate-Facet transform constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {Array<string>} [options.as] - output field names to use for each aggregated field in fields
* @param {boolean} [options.cross=false] - boolean indicating whether to include full cross-product of all groupby values in the aggregate output
* @param {Array<Field>} [options.fields=[<Field>]] - data fields for which to compute aggregate functions
* @param {Array<string>} [options.ops=['count']] - aggregation operations to apply to the fields
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {AggregateFacetTransform} aggregate-facet transform instance
*
* @example
* var transform = new AggregateFacetTransform();
* // returns <AggregateFacetTransform>
*/
function AggregateFacetTransform( options ) {
	var self;
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof AggregateFacetTransform ) ) {
		if ( arguments.length ) {
			return new AggregateFacetTransform( options );
		}
		return new AggregateFacetTransform();
	}
	EventEmitter.call( this );

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}

	// Validate provided options by attempting to assign option values to corresponding fields...
	if ( arguments.length ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		for ( i = 0; i < properties.length; i++ ) {
			k = properties[ i ];
			if ( !hasProp( options, k ) ) {
				continue;
			}
			v = options[ k ];
			try {
				this[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error. Error: %s', err.message );

				// FIXME: retain thrown error type
				throw new Error( transformErrorMessage( err.message ) );
			}
		}
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( AggregateFacetTransform, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof AggregateFacetTransform
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( AggregateFacetTransform, 'name', 'AggregateFacetTransform' );

/**
* Output field names to use for each aggregated field in fields.
*
* @name as
* @memberof AggregateFacetTransform.prototype
* @type {(Array<string>|void)}
*
* @example
* var transform = new AggregateFacetTransform({
*     'as': [ 'sum_field', 'average_field' ]
* });
*
* var v = transform.as;
* // returns [ 'sum_field', 'average_field' ]
*/
setReadWriteAccessor( AggregateFacetTransform.prototype, 'as', getAs, setAs );

/**
* Boolean indicating whether to include full cross-product of all groupby values in the aggregate output.
*
* @name cross
* @memberof AggregateFacetTransform.prototype
* @type {boolean}
* @default false
*
* @example
* var transform = new AggregateFacetTransform({
*     'cross': true
* });
*
* var v = transform.cross;
* // returns true
*/
setReadWriteAccessor( AggregateFacetTransform.prototype, 'cross', getCross, setCross );

/**
* Data fields for which to compute aggregate functions.
*
* @name fields
* @memberof AggregateFacetTransform.prototype
* @type {Array<Field>}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var fields = [
*     new Field({
*         'field': 'sum',
*         'as': 'sum_field'
*     }),
*     new Field({
*         'field': 'average',
*         'as': 'average_field'
*     })
* ]
* var transform = new AggregateFacetTransform({
*     'fields': fields
* });
*
* var v = transform.fields;
* // returns [ <Field>, <Field> ]
*/
setReadWriteAccessor( AggregateFacetTransform.prototype, 'fields', getFields, setFields );

/**
* Aggregation operations to apply to the fields.
*
* @name ops
* @memberof AggregateFacetTransform.prototype
* @type {Array<string>}
* @default ['count']
*
* @example
* var transform = new AggregateFacetTransform({
*     'ops': [ 'sum', 'average' ]
* });
*
* var v = transform.ops;
* // returns [ 'sum', 'average' ]
*/
setReadWriteAccessor( AggregateFacetTransform.prototype, 'ops', getOps, setOps );

/**
* Aggregate transform properties.
*
* @name properties
* @memberof AggregateFacetTransform.prototype
* @type {Array<string>}
*
* @example
* var transform = new AggregateFacetTransform();
*
* var v = transform.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( AggregateFacetTransform.prototype, 'properties', getProperties );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof AggregateFacetTransform.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var transform = new AggregateFacetTransform();
*
* var v = transform.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( AggregateFacetTransform.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = AggregateFacetTransform;
